import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Geometry & material for the textured plane
  const geometry = new ctx.THREE.PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });
  const plane = new ctx.THREE.Mesh(geometry, material);
  group.add(plane);

  // Apply cinematic primitives if any
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(group, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // Render text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  }

  // Event handlers container (none defined)
  group.userData.handlers = {};

  // Store timelines for cleanup (none created here but placeholder)
  group.userData._timelines = [];

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();

    // Dispose any text objects
    group.traverse((child) => {
      if (child !== group && child.isObject3D) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });

    // Cleanup primitives
    for (const handle of primitiveHandles) {
      if (handle?.cleanup) handle.cleanup();
    }

    // Kill GSAP timelines
    for (const tl of group.userData._timelines) {
      tl.kill();
    }
  };

  return group;
}
